{"file_path":"src/errors.js","content":"export class AppError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

export function usageError() {
  return new AppError('usage: cli.js waves|explain|pack <workers>', 2)
}

export function workersError() {
  return new AppError('workers must be a positive integer', 2)
}

export function lineError(lineNo, message) {
  return new AppError(`line ${lineNo}: ${message}`, 2)
}

export function unknownTaskError(name) {
  return new AppError(`unknown task ${name}`, 2)
}

export function cycleError(cycle) {
  return new AppError(`cycle: ${cycle.join(' -> ')}`, 3)
}
"}

