{"file_path":"src/parser.js","content":"import { lineError, unknownTaskError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set(dependency names)
  const usedNames = [] // names referenced by dep lines, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const kind = words[0]

    if (kind === 'task') {
      if (words.length !== 3) throw lineError(lineNo, 'expected task <name> <cost>')
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) throw lineError(lineNo, `invalid task name ${name}`)
      if (!COST_RE.test(costStr)) throw lineError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw lineError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costStr, 10))
    } else if (kind === 'dep') {
      if (words.length < 3) throw lineError(lineNo, 'expected dep <name> <dependency>...')
      const name = words[1]
      if (!NAME_RE.test(name)) throw lineError(lineNo, `invalid task name ${name}`)
      usedNames.push(name)
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (let j = 2; j < words.length; j++) {
        const dep = words[j]
        if (!NAME_RE.test(dep)) throw lineError(lineNo, `invalid task name ${dep}`)
        usedNames.push(dep)
        set.add(dep)
      }
    } else {
      throw lineError(lineNo, `unknown directive ${kind}`)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) throw unknownTaskError(name)
  }

  return { tasks, deps }
}
"}

