          if (p1 > p2 || (p1 === p2 && name < best)) best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = time + tasks.get(best)
      workerLogs[freeWorkerIdx].push({ name: best, start, finish })
      workerNextFree[freeWorkerIdx] = finish
