{"file_path":"src/parser.js","content":"import { lineError, unknownTaskError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set(dependency names)
  const usedNames = [] // names referenced by dep lines, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const kind = words[0]

    if (kind === 'task') {
      if (words.length !== 3) throw lineError(lineNo, 'expected task <name> <cost>')
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) throw lineError(lineNo, `invalid task name ${name}`)
      if (!COST_RE.test(costStr)) throw lineError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw lineError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costStr, 10))
    } else if (kind === 'dep') {
      if (words.length < 3) throw lineError(lineNo, 'expected dep <name> <dependency>...')
      const name = words[1]
      if (!NAME_RE.test(name)) throw lineError(lineNo, `invalid task name ${name}`)
      usedNames.push(name)
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (let j = 2; j < words.length; j++) {
        const dep = words[j]
        if (!NAME_RE.test(dep)) throw lineError(lineNo, `invalid task name ${dep}`)
        usedNames.push(dep)
        set.add(dep)
      }
    } else {
      throw lineError(lineNo, `unknown directive ${kind}`)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) throw unknownTaskError(name)
  }

  return { tasks, deps }
}
"}

{"file_path":"src/graph.js","content":"import { cycleError } from './errors.js'

export function detectCycle(tasks, deps) {
  const color = new Map() // 0 unvisited (default), 1 in-stack, 2 done
  const stack = []
  const sortedNames = [...tasks.keys()].sort()
  let cycleResult = null

  function dfs(node) {
    color.set(node, 1)
    stack.push(node)
    const depSet = deps.get(node)
    if (depSet) {
      const sortedDeps = [...depSet].sort()
      for (const d of sortedDeps) {
        if (cycleResult) return
        const c = color.get(d) || 0
        if (c === 1) {
          const idx = stack.indexOf(d)
          cycleResult = stack.slice(idx).concat(d)
          return
        } else if (c === 0) {
          dfs(d)
          if (cycleResult) return
        }
      }
    }
    if (cycleResult) return
    color.set(node, 2)
    stack.pop()
  }

  for (const n of sortedNames) {
    if (cycleResult) break
    if ((color.get(n) || 0) === 0) dfs(n)
  }

  return cycleResult
}

export function checkCycle(tasks, deps) {
  const cycle = detectCycle(tasks, deps)
  if (cycle) throw cycleError(cycle)
}

export function computeTimings(tasks, deps) {
  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const depSet = deps.get(name)
    let start = 0
    let depth = 0
    if (depSet && depSet.size > 0) {
      let maxFinish = 0
      let maxDepth = 0
      for (const d of depSet) {
        const info = compute(d)
        if (info.finish > maxFinish) maxFinish = info.finish
        if (info.depth > maxDepth) maxDepth = info.depth
      }
      start = maxFinish
      depth = maxDepth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}

export function computeWaves(timings) {
  const groups = new Map()
  let maxDepth = -1
  for (const [name, info] of timings) {
    if (!groups.has(info.depth)) groups.set(info.depth, [])
    groups.get(info.depth).push(name)
    if (info.depth > maxDepth) maxDepth = info.depth
  }
  const waves = []
  for (let k = 0; k <= maxDepth; k++) {
    waves.push((groups.get(k) || []).sort())
  }
  return waves
}

export function computeTotal(timings) {
  let total = 0
  for (const info of timings.values()) {
    if (info.finish > total) total = info.finish
  }
  return total
}

export function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const d of depSet) {
      if (!dependents.has(d)) dependents.set(d, [])
      dependents.get(d).push(name)
    }
  }

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const children = dependents.get(name) || []
    let best = 0
    for (const c of children) {
      const p = compute(c)
      if (p > best) best = p
    }
    const result = tasks.get(name) + best
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}

export function simulatePack(tasks, deps, priority, workers) {
  const remaining = new Set(tasks.keys())
  const finishMap = new Map()
  const workerNextFree = new Array(workers).fill(0)
  const workerLogs = Array.from({ length: workers }, () => [])
  let time = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorkerIdx = -1
      for (let i = 0; i < workers; i++) {
        if (workerNextFree[i] <= time) {
          freeWorkerIdx = i
          break
        }
      }
      if (freeWorkerIdx === -1) break

      let best = null
      for (const name of remaining) {
        const depSet = deps.get(name)
        let ready = true
        if (depSet) {
          for (const d of depSet) {
            const f = finishMap.get(d)
            if (f === undefined || f > time) {
              ready = false
              break
            }
          }
        }
        if (!ready) continue
        if (best === null) {
          best = name
        } else {
          const p1 = priority.get(name)
          const p2 = priority.get(best)
          if (p1 > p2 || (p1 === p2 && name < best)) best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = time + tasks.get(best)
      workerLogs[freeWorkerIdx].push({ name: best, start, finish })
      workerNextFree[freeWorkerIdx] = finish
      finishMap.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workers; i++) {
      if (workerNextFree[i] > time && workerNextFree[i] < next) next = workerNextFree[i]
    }
    if (next === Infinity) break // unreachable for an acyclic graph
    time = next
  }

  let makespan = 0
  for (const f of finishMap.values()) {
    if (f > makespan) makespan = f
  }

  return { workerLogs, makespan }
}
"}

