{"file_path":"src/graph.js","content":"import { cycleError } from './errors.js'

// Iterative DFS-based cycle detector. Avoids recursion so it copes with
// long dependency chains without blowing the call stack.
export function detectCycle(tasks, deps) {
  const color = new Map() // 0/absent = unvisited, 1 = in-stack, 2 = done
  const sortedNames = [...tasks.keys()].sort()
  const sortedDepsCache = new Map()

  function sortedDepsOf(name) {
    if (sortedDepsCache.has(name)) return sortedDepsCache.get(name)
    const depSet = deps.get(name)
    const arr = depSet ? [...depSet].sort() : []
    sortedDepsCache.set(name, arr)
    return arr
  }

  for (const start of sortedNames) {
    if ((color.get(start) || 0) !== 0) continue

    // Each frame: { node, deps, idx }
    const frames = [{ node: start, deps: sortedDepsOf(start), idx: 0 }]
    color.set(start, 1)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.idx < frame.deps.length) {
        const d = frame.deps[frame.idx]
        frame.idx++
        const c = color.get(d) || 0
        if (c === 1) {
          // Found a cycle: from d's position in the stack, through to the
          // top, back to d.
          const stackNames = frames.map((f) => f.node)
          const idx = stackNames.indexOf(d)
          return stackNames.slice(idx).concat(d)
        } else if (c === 0) {
          color.set(d, 1)
          frames.push({ node: d, deps: sortedDepsOf(d), idx: 0 })
        }
      } else {
        color.set(frame.node, 2)
        frames.pop()
      }
    }
  }

  return null
}

export function checkCycle(tasks, deps) {
  const cycle = detectCycle(tasks, deps)
  if (cycle) throw cycleError(cycle)
}

// Iterative post-order computation of start/finish/depth for every task,
// assuming the graph is acyclic (checked beforehand).
export function computeTimings(tasks, deps) {
  const memo = new Map()
  const visiting = new Set()

  for (const start of tasks.keys()) {
    if (memo.has(start)) continue

    const frames = [{ node: start, list: deps.get(start) ? [...deps.get(start)] : [], idx: 0 }]
    visiting.add(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.idx < frame.list.length) {
        const d = frame.list[frame.idx]
        frame.idx++
        if (!memo.has(d) && !visiting.has(d)) {
          visiting.add(d)
          frames.push({ node: d, list: deps.get(d) ? [...deps.get(d)] : [], idx: 0 })
        }
      } else {
        const name = frame.node
        const depSet = deps.get(name)
        let s = 0
        let dep = 0
        if (depSet && depSet.size > 0) {
          let maxFinish = 0
          let maxDepth = 0
          for (const d of depSet) {
            const info = memo.get(d)
            if (info.finish > maxFinish) maxFinish = info.finish
            if (info.depth > maxDepth) maxDepth = info.depth
          }
          s = maxFinish
          dep = maxDepth + 1
        }
        const finish = s + tasks.get(name)
        memo.set(name, { start: s, finish, depth: dep })
        visiting.delete(name)
        frames.pop()
      }
    }
  }

  return memo
}

export function computeWaves(timings) {
  const groups = new Map()
  let maxDepth = -1
  for (const [name, info] of timings) {
    if (!groups.has(info.depth)) groups.set(info.depth, [])
    groups.get(info.depth).push(name)
    if (info.depth > maxDepth) maxDepth = info.depth
  }
  const waves = []
  for (let k = 0; k <= maxDepth; k++) {
    waves.push((groups.get(k) || []).sort())
  }
  return waves
}

export function computeTotal(timings) {
  let total = 0
  for (const info of timings.values()) {
    if (info.finish > total) total = info.finish
  }
  return total
}

// Iterative post-order computation of the longest-chain priority for every
// task, walking the dependents graph (the reverse of the dependency graph).
export function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const d of depSet) {
      if (!dependents.has(d)) dependents.set(d, [])
      dependents.get(d).push(name)
    }
  }

  const memo = new Map()
  const visiting = new Set()

  for (const start of tasks.keys()) {
    if (memo.has(start)) continue

    const frames = [{ node: start, list: dependents.get(start) || [], idx: 0 }]
    visiting.add(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.idx < frame.list.length) {
        const c = frame.list[frame.idx]
        frame.idx++
        if (!memo.has(c) && !visiting.has(c)) {
          visiting.add(c)
          frames.push({ node: c, list: dependents.get(c) || [], idx: 0 })
        }
      } else {
        const name = frame.node
        const children = dependents.get(name) || []
        let best = 0
        for (const c of children) {
          const p = memo.get(c)
          if (p > best) best = p
        }
        memo.set(name, tasks.get(name) + best)
        visiting.delete(name)
        frames.pop()
      }
    }
  }

  return memo
}

export function simulatePack(tasks, deps, priority, workers) {
  const remaining = new Set(tasks.keys())
  const finishMap = new Map()
  const workerNextFree = new Array(workers).fill(0)
  const workerLogs = Array.from({ length: workers }, () => [])
  let time = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorkerIdx = -1
      for (let i = 0; i < workers; i++) {
        if (workerNextFree[i] <= time) {
          freeWorkerIdx = i
          break
        }
      }
      if (freeWorkerIdx === -1) break

      let best = null
      for (const name of remaining) {
        const depSet = deps.get(name)
        let ready = true
        if (depSet) {
          for (const d of depSet) {
            const f = finishMap.get(d)
            if (f === undefined || f > time) {
              ready = false
              break
            }
          }
        }
        if (!ready) continue
        if (best === null) {
          best = name
        } else {
          const p1 = priority.get(name)
          const p2 = priority.get(best)
          if (p1 > p2 || (p1 === p2 && name < best)) best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = time + tasks.get(best)
      workerLogs[freeWorkerIdx].push({ name: best, start, finish })
      workerNextFree[freeWorkerIdx] = finish
      finishMap.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workers; i++) {
      if (workerNextFree[i] > time && workerNextFree[i] < next) next = workerNextFree[i]
    }
    if (next === Infinity) break // unreachable for an acyclic graph
    time = next
  }

  let makespan = 0
  for (const f of finishMap.values()) {
    if (f > makespan) makespan = f
  }

  return { workerLogs, makespan }
}
